import { mkdir, writeFile } from "node:fs/promises";

import { rendererClientScript } from "../com.github.copilot/extensions/foundry-agent-playground/renderer/renderer-client.mjs";

const outputUrl = new URL("../com.github.copilot/extensions/foundry-agent-playground/renderer/dist/playground-client.js", import.meta.url);
const banner = [
    "// Generated by `npm run build` from renderer/renderer-client.mjs.",
    "// Do not edit this file directly.",
    "",
].join("\n");

await mkdir(new URL(".", outputUrl), { recursive: true });
await writeFile(outputUrl, banner + rendererClientScript + "\n", "utf8");
